const powerRatings = {
    "TV": 1200,
    "Lights": 200,
    "Kettle": 1500,
    "Flat iron": 100,
    "Woofa": 1000,
};

let states = flow.get("applianceStates") || {
    "TV": false,
    "Lights": false,
    "Kettle": false,
    "Flat iron": false,
    "Woofa":false,
};

if (msg.topic && powerRatings.hasOwnProperty(msg.topic)) {
    states[msg.topic] = Boolean(msg.payload);
    flow.set("applianceStates", states);
}

let total = 0;
for (let app in states) {
    if (states[app]) total += powerRatings[app];
}

msg.payload = total;
msg.topic = "Total Power";
return msg;
